export interface ConnectorConfig {
  /** Stripe webhook signing secret (from STRIPE_WEBHOOK_SECRET) */
  stripeWebhookSecret: string
  /** Mailchimp API key (from MAILCHIMP_API_KEY), format: {key}-{serverPrefix} e.g. abc123-us1 */
  mailchimpApiKey: string
  /** Mailchimp audience/list ID (from MAILCHIMP_LIST_ID) */
  mailchimpListId: string
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch
}

export interface StripeWebhookPayload {
  id: string
  type: 'checkout.session.completed'
  data: {
    object: StripeSessionObject
  }
}

export interface StripeSessionObject {
  id: string
  customer: string | StripeCustomer
  customer_email: string
  subscription: string | StripeSubscription
  payment_status: string
  mode: string
}

export interface StripeCustomer {
  id: string
  email: string
  [key: string]: unknown
}

export interface StripeSubscription {
  id: string
  items?: Array<{
    plan: {
      id: string
      nickname?: string
      [key: string]: unknown
    }
    [key: string]: unknown
  }>
  [key: string]: unknown
}

export interface HandleResult {
  mailchimpMemberId: string
  email: string
  tagsApplied: string[]
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function extractServerPrefix(apiKey: string): string {
  const parts = apiKey.split('-')
  return parts[parts.length - 1] ?? 'us1'
}

function buildMailchimpUrl(serverPrefix: string, listId: string): string {
  return `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${listId}/members`
}

function extractPlanTags(subscription: string | StripeSubscription): string[] {
  if (typeof subscription === 'string') {
    return []
  }
  const items = subscription.items
  if (!items || items.length === 0) {
    return []
  }
  const plan = items[0]?.plan
  if (!plan) {
    return []
  }
  const tags: string[] = []
  if (plan.id) {
    tags.push(plan.id)
  }
  if (plan.nickname && plan.nickname !== plan.id) {
    tags.push(plan.nickname)
  }
  return tags
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = getFetch(config)

  if (!payload || payload.type !== 'checkout.session.completed') {
    throw new Error('Invalid payload: expected checkout.session.completed event')
  }

  const session = payload.data?.object
  if (!session) {
    throw new Error('Invalid payload: missing data.object')
  }

  const email = session.customer_email
  if (!email) {
    throw new Error('Invalid payload: missing customer_email')
  }

  if (session.payment_status !== 'paid') {
    throw new Error(`Payment not completed: status is ${session.payment_status}`)
  }

  const tags = extractPlanTags(session.subscription)

  const serverPrefix = extractServerPrefix(config.mailchimpApiKey)
  const url = buildMailchimpUrl(serverPrefix, config.mailchimpListId)

  const body = {
    email_address: email,
    status_if_new: 'subscribed' as const,
    tags,
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.mailchimpApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Mailchimp API error: ${response.status} ${response.statusText} for POST ${url}: ${text}`
    )
  }

  const result = (await response.json()) as {
    id: string
    email_address: string
    tags?: Array<{ id: string; name: string }>
  }

  return {
    mailchimpMemberId: result.id,
    email: result.email_address,
    tagsApplied: tags,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, StripeWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      stripeWebhookSecret: 'whsec_test',
      mailchimpApiKey: 'testkey-us1',
      mailchimpListId: 'list_123',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.mailchimpMemberId).toBe('abc123')
    expect(result.email).toBe('customer@example.com')
    expect(result.tagsApplied).toEqual([])
  })
})

