    const payload: StripeWebhookPayload = {
      id: 'evt_test',
      type: 'checkout.session.completed',
      data: {
        object: {
          id: 'cs_test',
          customer: 'cus_123',
          customer_email: 'user@example.com',
          subscription: {
            id: 'sub_123',
            items: [
              {
                plan: {
