      email_address: 'user@example.com',
      status_if_new: 'subscribed',
      tags: ['plan_gold', 'Gold Plan'],
    })
    expect(result.mailchimpMemberId).toBe('mem_456')
    expect(result.tagsApplied).toEqual(['plan_gold', 'Gold Plan'])
