export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = getFetch(config)

  if (!payload || payload.type !== 'checkout.session.completed') {
    throw new Error('Invalid payload: expected checkout.session.completed event')
  }

  const session = payload.data?.object
  if (!session) {
    throw new Error('Invalid payload: missing data.object')
  }

  const email = session.customer_email
  if (!email) {
    throw new Error('Invalid payload: missing customer_email')
  }

  if (session.payment_status !== 'paid') {
    throw new Error(`Payment not completed: status is ${session.payment_status}`)
  }

  const tags = extractPlanTags(session.subscription)

  const serverPrefix = extractServerPrefix(config.mailchimpApiKey)
  const url = buildMailchimpUrl(serverPrefix, config.mailchimpListId)

  const body = {
    email_address: email,
    status_if_new: 'subscribed' as const,
    tags,
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.mailchimpApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(
      `Mailchimp API error: ${response.status} ${response.statusText} for POST ${url}: ${text}`
    )
  }

  const result = (await response.json()) as {
    id: string
    email_address: string
    tags?: Array<{ id: string; name: string }>
  }

  return {
    mailchimpMemberId: result.id,
    email: result.email_address,
    tagsApplied: tags,
  }
}

